// Property setter: Node2D::global_scale
static JSValue js_Node2D_set_global_scale(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "Node2D.global_scale setter: missing arguments");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Node2D.global_scale setter: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check write rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "Node2D.global_scale setter: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Node2D.global_scale setter: invalid object");
    }

    Node2D* typed_obj = Object::cast_to<Node2D>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Node2D.global_scale setter: wrong type");
    }

    double tmp_x_value, tmp_y_value;
    JSValue jx_value = JS_GetPropertyStr(ctx, argv[1], "x");
    JSValue jy_value = JS_GetPropertyStr(ctx, argv[1], "y");
    JS_ToFloat64(ctx, &tmp_x_value, jx_value);
    JS_ToFloat64(ctx, &tmp_y_value, jy_value);
    JS_FreeValue(ctx, jx_value);
    JS_FreeValue(ctx, jy_value);
    Vector2 value(tmp_x_value, tmp_y_value);
    typed_obj->set_global_scale(value);
    return JS_UNDEFINED;
}

